+// The audit log: one entry per request that may change data (docs/DATA.md).
+
+/** Appends an audit entry { at, key, method, path, status }. */
+export function recordAudit(store, entry) {
+  store.data.audit.push({ at: entry.at, key: entry.key, method: entry.method, path: entry.path, status: entry.status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
