+// API keys and roles: viewer reads, cook also does kitchen work, manager all.
+
+const COOK_POSTS = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** The key record for the request's `Authorization: Bearer <key>` header, or null. */
+export function findKey(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = name && /^Bearer (.+)$/.exec(String(headers[name]));
+  return (m && store.data.apiKeys.find((k) => k.key === m[1])) || null;
+}
+
+/** Whether `role` may call `method` on `path`. */
+export function allowed(role, method, path) {
+  if (role === "manager") return true;
+  if (path === "/audit") return false;
+  if (method === "GET") return role === "viewer" || role === "cook";
+  return role === "cook" && method === "POST" && COOK_POSTS.some((re) => re.test(path));
+}
